const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function readLocal(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback}catch{return fallback}}
function writeLocal(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}}
const edits=document.body.dataset.mode==='launch'?{}:readLocal('ge-consolidated-copy',{});
$$('[data-copy]').forEach(el=>{if(typeof edits[el.dataset.copy]==='string'&&edits[el.dataset.copy].trim())el.textContent=edits[el.dataset.copy]});
$$('.blocker>button').forEach(button=>button.addEventListener('click',()=>{const row=button.parentElement,opening=button.getAttribute('aria-expanded')!=='true';$$('.blocker').forEach(el=>{el.classList.remove('active');el.querySelector('button').setAttribute('aria-expanded','false');el.querySelector('.answer').hidden=true;el.querySelector('.plus').textContent='+'});if(opening){row.classList.add('active');button.setAttribute('aria-expanded','true');row.querySelector('.answer').hidden=false;row.querySelector('.plus').textContent='−'}}));
function pause(id,target,what){$(id)?.addEventListener('click',()=>{const paused=$(target).classList.toggle('paused');$(id).setAttribute('aria-pressed',String(paused));$(id).textContent=(paused?'Play ':'Pause ')+what})}pause('#pauseLogos','.marquee-track','logos');pause('#pauseDemos','.services','animations');
const call=$('#call');let callBrief='';function openCall(area,challenge){if(!call)return;if(area)$('#callArea').value=area;if(challenge)$('#callChallenge').value=challenge;$('#callOutput').hidden=true;call.showModal()}
$$('[data-call]').forEach(b=>b.addEventListener('click',()=>openCall(b.dataset.area)));$('.close')?.addEventListener('click',()=>call.close());call?.addEventListener('click',e=>{if(e.target===call){const r=call.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)call.close()}});
$('#callForm')?.addEventListener('submit',e=>{e.preventDefault();callBrief='Growth Element — 30-minute conversation\nFocus: '+$('#callArea').value+'\nChallenge: '+$('#callChallenge').value.trim();$('#callText').textContent=callBrief;$('#callOutput').hidden=false});
$('#copyCall')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(callBrief);$('#callStatus').textContent='Copied. Nothing has been sent or booked.'}catch{$('#callStatus').textContent='Select and copy the brief above. Clipboard access is unavailable.'}});
function calcValues(people,hours,rate,reduction){const p=Math.max(1,Math.min(500,Number(people)||1)),h=Math.max(0,Math.min(40,Number(hours)||0)),r=Math.max(0,Math.min(10000,Number(rate)||0)),s=Math.max(0,Math.min(80,Number(reduction)||0));return{people:p,hours:h,rate:r,reduction:s,weekly:p*h*s/100,monthly:p*h*s/100*52/12*r,annual:p*h*s/100*52}}
let savingsPeriod='month';
function updateCalculator(){const v=calcValues($('#peopleCount').value,$('#weeklyHours').value,$('#hourlyRate').value,$('#reduction').value);const multiplier={week:1,month:52/12,year:52}[savingsPeriod];const fmt=n=>Number(n.toFixed(1)).toLocaleString('en-US');const money=n=>'$'+Math.round(n).toLocaleString('en-US');$('#hoursLabel').textContent=v.hours+' h';$('#reductionLabel').textContent=v.reduction+'%';$('#weeklySaved').textContent=fmt(v.weekly*multiplier)+' hours';$('#monthlyValue').textContent=money(v.weekly*multiplier*v.rate);$('#timePeriod').textContent='each '+savingsPeriod;$('#moneyPeriod').textContent='each '+savingsPeriod;$('#annualTime').textContent='That’s '+fmt(v.annual)+' hours and '+money(v.annual*v.rate)+' worth of time over a year.';$('#timeBefore').textContent=fmt(v.people*v.hours*multiplier)+' hours / '+savingsPeriod;$('#timeAfter').textContent=fmt((v.people*v.hours-v.weekly)*multiplier)+' hours / '+savingsPeriod;return v}
$$('[data-period]').forEach(button=>button.addEventListener('click',()=>{savingsPeriod=button.dataset.period;$$('[data-period]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));updateCalculator()}));
if($('#weeklyHours')){$$('.calculator input').forEach(el=>el.addEventListener('input',updateCalculator));['#peopleCount','#hourlyRate'].forEach(id=>$(id).addEventListener('change',()=>{const v=updateCalculator();$(id).value=id==='#peopleCount'?v.people:v.rate}));updateCalculator();if(call)$('#discussCalc').addEventListener('click',()=>{const v=updateCalculator();openCall('AI & Workflows',($('#task').value.trim()||'A recurring workflow')+'\nScenario: '+v.people+' people × '+v.hours+' hours/week, '+v.reduction+'% reduction, $'+v.rate+'/hour. Potential capacity: '+Number(v.weekly.toFixed(1))+' hours/week. Assumptions to validate, not guaranteed savings.')})}
const goals={growth:'More space for customer conversations, follow-ups and the decisions only you can make.',creative:'Protected time for the idea, campaign or project that keeps getting pushed to next week.',life:'A little less work following you home. Decide where your recovered time would matter most.'};$$('[data-goal]').forEach(b=>b.addEventListener('click',()=>{$$('[data-goal]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});$('#goalText').textContent=goals[b.dataset.goal]}));
let notes=readLocal('ge-consolidated-notes',[]);if(!Array.isArray(notes))notes=[];let defaults={};
function renderNotes(){const box=$('#savedNotes');if(!box)return;box.replaceChildren();notes.forEach((n,i)=>{let card=document.createElement('div');card.className='saved-note';let remove=document.createElement('button');remove.textContent='Remove';remove.type='button';remove.addEventListener('click',()=>{notes.splice(i,1);writeLocal('ge-consolidated-notes',notes);renderNotes()});let title=document.createElement('strong');title.textContent=n.name+' / '+n.section;let text=document.createElement('p');text.textContent=n.note;card.append(remove,title,text);box.append(card)})}
if($('#copyEditor')){fetch('content.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{defaults=data;for(const [key,value] of Object.entries(data)){let label=document.createElement('label');label.htmlFor='edit-'+key;label.textContent=key.replaceAll('_',' ');let input=document.createElement('textarea');input.id='edit-'+key;input.name=key;input.maxLength=1200;input.value=typeof edits[key]==='string'?edits[key]:value;$('#copyEditor').append(label,input)}}).catch(()=>{$('#editStatus').textContent='The copy editor could not load. The site is unchanged.'});$('#saveCopy').addEventListener('click',()=>{const values={};$$('#copyEditor textarea').forEach(el=>{if(el.value.trim())values[el.name]=el.value.trim()});$('#editStatus').textContent=writeLocal('ge-consolidated-copy',values)?'Saved in this browser. Open the homepage to preview. Published source is unchanged.':'This browser could not save your changes. Keep this page open and export them.'});$('#resetCopy').addEventListener('click',()=>{writeLocal('ge-consolidated-copy',{});$$('#copyEditor textarea').forEach(el=>el.value=defaults[el.name]||'');$('#editStatus').textContent='Local copy reset to the published draft.'});$('#noteForm').addEventListener('submit',e=>{e.preventDefault();notes.push({name:$('#reviewer').value.trim(),section:$('#sectionName').value,note:$('#reviewNote').value.trim(),time:new Date().toISOString()});writeLocal('ge-consolidated-notes',notes);$('#reviewNote').value='';renderNotes()});renderNotes();$('#exportReview').addEventListener('click',()=>{const copy={};$$('#copyEditor textarea').forEach(el=>copy[el.name]=el.value);const blob=new Blob([JSON.stringify({project:'Growth Element consolidated draft',date:new Date().toISOString(),copy,notes},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Growth-Element-Review.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
